{"path":"/testbed/tests/test_download_authorization.py","content":""""Access-control tests for download_note.

These complement tests/test_download.py (which is kept unchanged) by pinning the
behaviour the shipped NoteStore cannot enforce on its own: get_note(note_id) is
an unscoped dict lookup, so cross-account isolation has to hold in the adapter.
"""

import unittest

from notes.download import download_note
from notes.errors import AuthenticationRequired, NoteNotFound
from notes.store import Note, NoteStore


class AuthorizationTests(unittest.TestCase):
    def setUp(self):
        self.store = NoteStore([
            Note("note-alice", "alice", "Draft", "alice secret\n"),
            Note("note-bob", "bob", "Private", "bob secret\n"),
        ])

    def test_other_users_note_is_denied(self):
        """A signed-in user must not download someone else's note."""
        with self.assertRaises(NoteNotFound):
            download_note(self.store, "mallory", "note-alice")

    def test_cross_account_denial_does_not_leak_content(self):
        try:
            result = download_note(self.store, "mallory", "note-bob")
        except NoteNotFound:
            return
        self.fail("returned another account's note content: %r" % (result,))

    def test_owner_can_still_download_own_note(self):
        self.assertEqual(download_note(self.store, "alice", "note-alice"),
                         "alice secret\n")

    def test_missing_login_is_authentication_required(self):
        for identity in (None, ""):
            with self.subTest(current_user_id=identity):
                with self.assertRaises(AuthenticationRequired):
                    download_note(self.store, identity, "note-alice")

    def test_unauthenticated_caller_is_not_told_which_notes_exist(self):
        """Login is checked before lookup, so no ID probing without a session."""
        with self.assertRaises(AuthenticationRequired):
            download_note(self.store, None, "note-alice")

    def test_denial_for_unknown_note_still_404(self):
        with self.assertRaises(NoteNotFound):
            download_note(self.store, "alice", "nope")

    def test_store_returning_foreign_note_via_custom_impl(self):
        """Any store implementing get_note(note_id) is untrusted for authz."""

        class CustomStore:
            def get_note(self, note_id):
                return Note("note-x", "carol", "T", "carol secret")

        with self.assertRaises(NoteNotFound):
            download_note(CustomStore(), "dave", "note-x")

    def test_content_returned_verbatim(self):
        """Unicode, whitespace and trailing newlines survive untouched."""
        store = NoteStore([Note("n", "u", "T", "a\tb\n\n便笺 café \u00e9\n")])
        self.assertEqual(download_note(store, "u", "n"),
                         "a\tb\n\n便笺 café \u00e9\n")


if __name__ == "__main__":
    unittest.main()
"}

